function queueRecord(record,all,now=Date.now()){
 const f=record?.fields||{},workspace=f['Workspace Record ID'];
 if(!/^rec[A-Za-z0-9]{14}$/.test(workspace||''))return null;
 if(all.filter(r=>r.fields?.['Workspace Record ID']===workspace).length!==1)return null;
 let request=null,result=null;try{request=JSON.parse(f['Calendar Connection Request JSON']||'null');result=JSON.parse(f['Calendar Connection Result JSON']||'null')}catch{}
 const at=Date.parse(request?.requestedAt||'');
 const eligible=request&&/^[A-Za-z0-9_-]{12,100}$/.test(request.requestId||'')&&request.provider==='google'&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(request.email||'')&&at<=now+10000&&at>now-86400000&&result?.requestId!==request.requestId;
 return {recordId:record.id,workspace,request:eligible?request:null};
}
function connectionResult(input,response,current,now=Date.now()){
 let request;try{request=JSON.parse(current?.fields?.['Calendar Connection Request JSON']||'{}')}catch{return null;}
 if(current?.id!==input.recordId||current.fields?.['Workspace Record ID']!==input.workspace||request.requestId!==input.request?.requestId||request.email!==input.request.email||request.provider!==input.request.provider)return null;
 const url=response?.url||'',valid=/^https:\/\/n8n\.dulcy\.io\/calendar\/connect\?ticket=[A-Za-z0-9_-]{40,100}$/.test(url)&&response.workspaceId===input.workspace&&Date.parse(response.expiresAt)>now&&Date.parse(response.expiresAt)<=now+86410000;
 return {requestId:input.request.requestId,status:valid?'Ready':'Needs Attention',...(valid?{url,expiresAt:response.expiresAt}:{}),message:valid?'Open this one-time link and sign in as '+input.request.email+'.':'Connection link could not be created. Google is currently limited to enabled test accounts; ask your administrator to check access.',updatedAt:new Date(now).toISOString()};
}
function connectionSnapshot(input,response,now=Date.now()){
 if(response?.workspaceId!==input.workspace||!['Connected','Not Connected','Disconnected','Selection Required','Reconnect Required'].includes(response.status))return null;
 return {workspaceId:input.workspace,status:response.status,provider:response.provider||null,accountEmail:response.accountEmail||null,revision:response.revision||0,checkedAt:new Date(now).toISOString()};
}

